import { ArrowDownToLine, ArrowRight, ArrowUpRight, Bell, BookOpen, CalendarDays, ChartNoAxesCombined, Check, CheckCheck, ChevronLeft, ChevronRight, CircleHelp, Clock3, Crown, Flame, Footprints, GraduationCap, LayoutDashboard, Menu, Moon, Mountain, Plus, RotateCcw, Settings2, ShieldCheck, Snowflake, Sparkles, Star, Sun, Target, TrendingUp, Trophy, Upload, X, Zap, Calculator } from 'lucide-react'
import type { LucideIcon } from 'lucide-react'
import { act, addDays, BADGES, complete, count, dates, dayDiff, dayXP, decode, getDay, level, MILESTONES, parseDate, PRACTICE, progress, reconcile, required, START, status, streaks, totalXP, updateSettings, weekStart, weekStats } from './engine'
