      <div className="sidebar-bottom"><button className={`nav-item ${page === 'settings' ? 'active' : ''}`} onClick={() => navigate('settings')}><Settings2 size={19} /> Settings</button><button className="nav-item" onClick={() => notify('Log your question-bank practice here. Finish both subjects to build your streak. One freeze is ready when you need a break.')}><CircleHelp size={19} /> How it works</button><div className="profile"><div className="avatar">Y</div><div><strong>Your workspace</strong><span>Personal study plan</span></div><ShieldCheck size={16} /></div></div>
