function CalendarPage({ state, today, selectDay }: { state: State; today: string; selectDay: (k: string) => void }) {
  const [month, setMonth] = useState(today.slice(0, 7) + '-01')
  const end = new Date(parseDate(month).getFullYear(), parseDate(month).getMonth() + 1, 0).getDate()
  const startOffset = (parseDate(month).getDay() + 6) % 7
  const changeMonth = (n: number) => { const d = parseDate(month); d.setMonth(d.getMonth() + n); setMonth(`${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-01`) }
  return <><PageHeading eyebrow="CONSISTENCY, MADE VISIBLE" title="Your study calendar." description="Every little square is a step toward something bigger." /><section className="card calendar-card"><div className="card-heading"><div><h2>{format(month, { month: 'long', year: 'numeric' })}</h2><p className="card-subtitle">Select a day to explore your progress.</p></div><div className="calendar-controls"><button className="secondary-button" onClick={() => setMonth(today.slice(0, 7) + '-01')}>Today</button><button className="icon-button" onClick={() => changeMonth(-1)} aria-label="Previous month"><ChevronLeft size={19} /></button><button className="icon-button" onClick={() => changeMonth(1)} aria-label="Next month"><ChevronRight size={19} /></button></div></div><div className="calendar-weekdays">{['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'].map(d => <span key={d}>{d}</span>)}</div><div className="calendar-grid">{Array.from({ length: startOffset }, (_, i) => <div key={`blank${i}`} />)}{Array.from({ length: end }, (_, i) => {
    const key = addDays(month, i), d = getDay(state, key), st = status(state, key, today)
    return <button className={`calendar-day ${st} ${key === today ? 'today' : ''}`} key={key} onClick={() => selectDay(key)} title={`${format(key)} · English ${count(d, 'english')}/${d.englishTarget} · Math ${count(d, 'math')}/${d.mathTarget} · ${pct(progress(d))}% · ${dayXP(d)} XP · ${st}`} aria-label={`${format(key)}: ${st}`}><span className="calendar-date">{i + 1}{st === 'complete' ? <Check size={16} /> : st === 'frozen' ? <Snowflake size={16} /> : d.practice && st !== 'outside' ? <BookOpen size={15} /> : key === today ? <span className="tiny-dot" /> : null}</span><span className="calendar-day-label">{st === 'outside' ? '' : d.practice ? 'Practice test' : `${count(d, 'english') + count(d, 'math')} questions`}</span>{st !== 'outside' && <Meter value={progress(d)} />}</button>
  })}</div><div className="calendar-legend">{[['pending', 'Not started'], ['partial', 'In progress'], ['complete', 'Completed'], ['frozen', 'Freeze used'], ['missed', 'Missed'], ['today', 'Today']].map(([s, label]) => <span key={s}><i className={s} />{label}</span>)}</div></section><div className="two-columns"><section className="card info-card"><IconBox icon={Snowflake} color="math" /><h3>A little breathing room.</h3><p>You have {streaks(state, today).freezes} of 2 freezes. An active streak is protected automatically if you miss a day. Earn another freeze every 7 completed study days.</p></section><section className="card info-card"><IconBox icon={Flame} color="orange" /><h3>Progress that stays with you.</h3><p>Complete both subjects, or the scheduled practice test, to add a day to your streak. Review tasks are optional. Today stays pending until you finish.</p></section></div></>
}
function Statistics({ state, today }: { state: State; today: string }) {
  const systemReduced = useReducedMotion()
  const [week, setWeek] = useState(weekStart(today)), [view, setView] = useState<'questions' | 'completion'>('questions')
  const w = weekStats(state, week), prev = weekStats(state, addDays(week, -7)), s = streaks(state, today)
  const chart = dates(week, addDays(week, 6)).map(k => { const d = getDay(state, k); return { name: format(k, { weekday: 'short' }), date: k, English: required(state, k) ? count(d, 'english') : 0, Math: required(state, k) ? count(d, 'math') : 0, Completion: required(state, k) ? pct(progress(d)) : 0 } })
  const best = chart.reduce((a, b) => b.English + b.Math > a.English + a.Math ? b : a), total = w.english + w.math, previous = prev.english + prev.math
  const tooltipStyle = { backgroundColor: 'var(--surface)', border: '1px solid var(--border)', borderRadius: 12, color: 'var(--text)' }
  return <><PageHeading eyebrow="THE BIGGER PICTURE" title="Look how far you’ve come." description="Your effort, translated into progress you can see."><div className="calendar-controls"><button className="icon-button" aria-label="Previous week" onClick={() => setWeek(addDays(week, -7))}><ChevronLeft size={18} /></button><span>{format(week, { month: 'short', day: 'numeric' })} – {format(addDays(week, 6), { month: 'short', day: 'numeric' })}</span><button className="icon-button" aria-label="Next week" onClick={() => setWeek(addDays(week, 7))}><ChevronRight size={18} /></button></div></PageHeading><div className="stats-grid">{[{ label: 'Questions this week', value: total, caption: `${total - previous >= 0 ? '+' : ''}${total - previous} vs previous week`, icon: BookOpen }, { label: 'Completed study days', value: `${w.completed}/${w.plannedDays}`, caption: 'Practice tests count, too', icon: CheckCheck }, { label: 'Average completion', value: `${pct(w.progress)}%`, caption: 'Across planned days this week', icon: Target }, { label: 'Weekly XP', value: number(w.xp), caption: 'Every bit of effort adds up', icon: Zap }].map(item => <section className="card stat-block" key={item.label}><div><span>{item.label}</span><item.icon size={18} /></div><strong>{item.value}</strong><small>{item.caption}</small></section>)}</div><section className="card chart-card"><div className="card-heading"><div><h3>Your weekly rhythm</h3><p className="card-subtitle">A little more confident, one session at a time.</p></div><div className="segmented"><button className={view === 'questions' ? 'active' : ''} onClick={() => setView('questions')}>Questions</button><button className={view === 'completion' ? 'active' : ''} onClick={() => setView('completion')}>Completion</button></div></div><div className="chart" role="img" aria-label={chart.map(d => `${d.name}: ${d.English} English, ${d.Math} Math, ${d.Completion}% complete`).join('; ')}><ResponsiveContainer width="100%" height="100%">{view === 'questions' ? <BarChart data={chart} barGap={6} margin={{ top: 20, right: 10, bottom: 0, left: -20 }}><CartesianGrid vertical={false} stroke="var(--border)" strokeDasharray="3 5" /><XAxis dataKey="name" tickLine={false} axisLine={false} tick={{ fill: 'var(--muted)', fontSize: 12 }} /><YAxis allowDecimals={false} tickLine={false} axisLine={false} tick={{ fill: 'var(--muted)', fontSize: 12 }} /><Tooltip contentStyle={tooltipStyle} cursor={{ fill: 'var(--hover)' }} /><Bar dataKey="English" fill="#b99af0" radius={[5, 5, 0, 0]} maxBarSize={30} isAnimationActive={state.settings.animations && !state.settings.reducedMotion && !systemReduced} /><Bar dataKey="Math" fill="#8bb2f5" radius={[5, 5, 0, 0]} maxBarSize={30} isAnimationActive={state.settings.animations && !state.settings.reducedMotion && !systemReduced} /></BarChart> : <AreaChart data={chart} margin={{ top: 20, right: 10, bottom: 0, left: -20 }}><defs><linearGradient id="chartFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#c6ef83" stopOpacity={.25} /><stop offset="100%" stopColor="#c6ef83" stopOpacity={0} /></linearGradient></defs><CartesianGrid vertical={false} stroke="var(--border)" strokeDasharray="3 5" /><XAxis dataKey="name" tickLine={false} axisLine={false} tick={{ fill: 'var(--muted)' }} /><YAxis domain={[0, 100]} tickLine={false} axisLine={false} tick={{ fill: 'var(--muted)' }} /><Tooltip contentStyle={tooltipStyle} /><Area dataKey="Completion" stroke="#c6ef83" fill="url(#chartFill)" strokeWidth={3} isAnimationActive={state.settings.animations && !state.settings.reducedMotion && !systemReduced} /></AreaChart>}</ResponsiveContainer></div><div className="chart-legend"><span><i className="purple-dot" />English <b>{w.english}</b></span><span><i className="blue-dot" />Math <b>{w.math}</b></span><span className="muted">Weekly goals reset on Monday. Your history stays.</span></div></section><div className="three-columns"><section className="card info-card"><IconBox icon={Flame} color="orange" /><span className="stat-label">Current streak</span><h2>{s.current} days</h2><p>Your longest streak is {s.longest} days. Every fresh start matters.</p></section><section className="card info-card"><IconBox icon={Star} color="gold" /><span className="stat-label">Most productive day</span><h2>{best.English + best.Math ? format(best.date, { weekday: 'long' }) : 'A fresh canvas'}</h2><p>{best.English + best.Math ? `${best.English + best.Math} questions completed. That’s time well spent.` : 'Log your first questions to find your weekly rhythm.'}</p></section><section className="card info-card"><IconBox icon={TrendingUp} color="green" /><span className="stat-label">Week over week</span><h2>{previous ? `${Math.round((total - previous) / previous * 100) >= 0 ? '+' : ''}${Math.round((total - previous) / previous * 100)}%` : total ? 'A strong start' : 'Your pace'}</h2><p>{total} questions this week compared with {previous} last week. Aim for sustainable progress.</p></section></div></>
}
function Achievements({ state }: { state: State }) {
  const unlocked = Object.keys(state.achievements).length
  return <><PageHeading eyebrow="LITTLE WINS. LASTING CONFIDENCE." title="Your hall of progress." description="These aren’t just badges. They’re reminders that you showed up."><span className="achievement-count"><Trophy size={17} /> {unlocked} of {BADGES.length} unlocked</span></PageHeading><section className="card achievement-banner"><div><Sparkles size={26} /><h2>Great things take practice.</h2><p>Keep doing your thing. The milestones will follow.</p></div><div><strong>{unlocked}<span> / {BADGES.length}</span></strong><Meter value={unlocked / BADGES.length} /></div></section><div className="achievement-grid">{BADGES.map((badge, i) => { const Icon = badgeIcons[badge.icon], earned = state.achievements[badge.id]; return <motion.section key={badge.id} className={`card badge-card ${earned ? 'unlocked' : 'locked'}`} initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * .035 }}><div className="badge-top"><span>{String(i + 1).padStart(2, '0')}</span>{earned ? <Check size={17} /> : <span className="badge-lock">TO BE EARNED</span>}</div><div className={`badge-emblem badge-${i % 4}`}><Icon size={38} strokeWidth={1.5} /></div><h3>{badge.name}</h3><p>{badge.description}</p><span className="badge-date">{earned ? `Unlocked ${format(earned, { month: 'short', day: 'numeric' })}` : 'Your next chapter is waiting'}</span></motion.section> })}</div></>
}
function PracticeMission({ day, dispatch, disabled }: { day: Day; dispatch: (a: Action) => void; disabled: boolean }) {
  const [english, setEnglish] = useState(day.test.english?.toString() ?? ''), [math, setMath] = useState(day.test.math?.toString() ?? '')
  const valid = [english, math].every(n => n === '' || Number(n) >= 200 && Number(n) <= 800 && Number(n) % 10 === 0)
  return <section className="card practice-mission"><IconBox icon={GraduationCap} color="english" /><span className="eyebrow">TODAY’S BIG PICTURE</span><h2>{day.test.completed ? 'Another test. More perspective.' : 'Put your practice into perspective.'}</h2><p>A full-length SAT practice test replaces today’s question targets. Complete it to keep your streak and earn 100 XP.</p><form onSubmit={e => { e.preventDefault(); if (valid) dispatch({ type: 'test', completed: true, english: english ? Number(english) : null, math: math ? Number(math) : null }) }}><div className="score-inputs"><label>English score<input type="number" min="200" max="800" step="10" placeholder="200–800" value={english} onChange={e => setEnglish(e.target.value)} disabled={disabled} /></label><span>+</span><label>Math score<input type="number" min="200" max="800" step="10" placeholder="200–800" value={math} onChange={e => setMath(e.target.value)} disabled={disabled} /></label><span>=</span><div><span>Total score</span><strong>{english && math && valid ? Number(english) + Number(math) : '—'}</strong></div></div><small className="muted">Scores are optional. Enter section scores in increments of 10.</small><div className="practice-actions"><button className="primary-button" type="submit" disabled={disabled || !valid}><Check size={17} /> {day.test.completed ? 'Save scores' : 'Mark practice test complete'}</button>{day.test.completed && <button className="text-button" type="button" disabled={disabled} onClick={() => dispatch({ type: 'test', completed: false, english: day.test.english, math: day.test.math })}><RotateCcw size={14} /> Undo completion</button>}</div></form></section>
}
function Practice({ state, today, dispatch, disabled }: { state: State; today: string; dispatch: (a: Action) => void; disabled: boolean }) {
  const systemReduced = useReducedMotion()
  const records = PRACTICE.filter(k => k < state.settings.exam)
  const scored = records.filter(k => { const t = getDay(state, k).test; return t.completed && t.english !== null && t.math !== null })
  const points = [{ date: 'Starting score', Total: 1300, English: 570, Math: 730 }, ...scored.map(k => { const t = getDay(state, k).test; return { date: format(k, { month: 'short', day: 'numeric' }), Total: t.english! + t.math!, English: t.english!, Math: t.math! } })]
  const latest = points[points.length - 1]
  return <><PageHeading eyebrow="PRACTICE WITH PURPOSE" title="The dress rehearsals." description="Three chances to build confidence before the big day." /><div className="stats-grid"><section className="card stat-block"><span>Latest total score</span><strong>{latest.Total}</strong><small>{points.length === 1 ? 'Your starting score' : `${latest.Total - 1300 >= 0 ? '+' : ''}${latest.Total - 1300} since your starting score`}</small></section><section className="card stat-block"><span>English · target 650+</span><strong className="purple">{latest.English}</strong><small>{Math.max(0, 650 - latest.English)} points to section goal</small></section><section className="card stat-block"><span>Math · target 750+</span><strong className="blue">{latest.Math}</strong><small>{Math.max(0, 750 - latest.Math)} points to section goal</small></section><section className="card stat-block"><span>Your total target</span><strong className="green">{state.settings.target}+</strong><small>{Math.max(0, state.settings.target - latest.Total)} points to go</small></section></div>{PRACTICE.includes(today) && required(state, today) && <PracticeMission key={today} day={getDay(state, today)} dispatch={dispatch} disabled={disabled} />}<section className="card chart-card"><div className="card-heading"><div><h3>Your score story</h3><p className="card-subtitle">One test is a snapshot. Your trend tells the story.</p></div><span className="mini-tag">TARGET {state.settings.target}+</span></div><div className="chart" role="img" aria-label={points.map(p => `${p.date}: total score ${p.Total}`).join('; ')}><ResponsiveContainer width="100%" height="100%"><LineChart data={points} margin={{ top: 30, left: 5, right: 35, bottom: 0 }}><CartesianGrid stroke="var(--border)" vertical={false} strokeDasharray="3 5" /><XAxis dataKey="date" tick={{ fill: 'var(--muted)', fontSize: 12 }} tickLine={false} axisLine={false} /><YAxis domain={[Math.min(1000, ...points.map(p => p.Total - 100)), 1600]} tick={{ fill: 'var(--muted)', fontSize: 12 }} tickLine={false} axisLine={false} /><Tooltip contentStyle={{ background: 'var(--surface)', border: '1px solid var(--border)', borderRadius: 12 }} /><ReferenceLine y={state.settings.target} stroke="#c6ef83" strokeDasharray="5 5" label={{ value: 'Your goal', fill: 'var(--lime)', position: 'insideTopRight' }} /><Line dataKey="Total" stroke="#bc9bf3" strokeWidth={3} dot={{ r: 6, fill: '#bc9bf3', strokeWidth: 4, stroke: 'var(--surface)' }} activeDot={{ r: 8 }} isAnimationActive={state.settings.animations && !state.settings.reducedMotion && !systemReduced} /></LineChart></ResponsiveContainer></div></section><div className="section-heading"><div><h2>Your practice schedule</h2><p>Test days replace the regular mission. No extra questions required.</p></div></div><div className="practice-schedule">{records.map((key, i) => { const d = getDay(state, key), t = d.test, passed = key < today; const previous = [...scored].filter(k => k < key).at(-1), priorScore = previous ? getDay(state, previous).test.english! + getDay(state, previous).test.math! : 1300; const total = t.english !== null && t.math !== null ? t.english + t.math : null; return <section className={`card scheduled-test ${t.completed ? 'finished' : ''}`} key={key}><div className="test-date"><span>{format(key, { month: 'short' })}</span><strong>{parseDate(key).getDate()}</strong></div><div className="scheduled-info"><span className="eyebrow">PRACTICE TEST {String(i + 1).padStart(2, '0')}</span><h3>Full-length SAT practice</h3><span>{format(key, { weekday: 'long' })} · English + Math · +100 XP</span></div><div className="scheduled-result">{t.completed ? <><strong>{total ?? 'Completed'}{total !== null && <span>/ 1600</span>}</strong><small>{total !== null ? `${total - priorScore >= 0 ? '+' : ''}${total - priorScore} vs previous score` : 'Scores not entered'}</small></> : <span className={`mini-tag ${key === today ? 'green' : ''}`}>{key === today ? 'TODAY’S MISSION' : passed ? d.frozen ? 'FREEZE USED' : 'NOT COMPLETED' : `IN ${dayDiff(today, key)} DAYS`}</span>}</div></section> })}</div><p className="muted small-text">Log tests on their scheduled day. Past dates are read-only to protect streak history. Scores are self-reported and stored only on this device.</p></>
}
function SettingsPage({ state, today, onSave, onImport, notify }: { state: State; today: string; onSave: (s: Settings) => Promise<void>; onImport: (s: State) => Promise<void>; notify: (s: string) => void }) {
  const [draft, setDraft] = useState({ ...state.settings }), [pending, setPending] = useState<State | null>(null), [importError, setImportError] = useState('')
  const input = useRef<HTMLInputElement>(null)
  const field = <K extends keyof Settings>(key: K, value: Settings[K]) => setDraft(s => ({ ...s, [key]: value }))
  function exportData() { const blob = new Blob([JSON.stringify(state, null, 2)], { type: 'application/json' }); const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.href = url; a.download = `ascend-progress-${today}.json`; a.click(); setTimeout(() => URL.revokeObjectURL(url), 1000); notify('Progress exported. Keep your backup somewhere safe.') }
  async function importFile(file: File) { try { if (file.size > 5_000_000) throw new Error('Choose a progress export under 5 MB.'); const imported = decode(await file.text()); setPending(imported); setImportError('') } catch (e) { setImportError(e instanceof Error ? e.message : 'Unable to read this file.') } }
  async function submit(e: FormEvent) { e.preventDefault(); await onSave(draft) }
  return <><PageHeading eyebrow="MAKE IT YOURS" title="A plan that fits your life." description="Adjust the details. Keep the bigger picture." /><form onSubmit={submit} className="settings-form"><section className="card settings-card"><div className="settings-intro"><IconBox icon={Target} color="green" /><div><h3>Your study goals</h3><p>New targets apply to future, unopened study days. Today’s plan and your history stay intact.</p></div></div><div className="settings-fields"><label>Daily English target<input aria-label="Daily English target" type="number" min="1" max="10000" required value={draft.english} onChange={e => field('english', Number(e.target.value))} /><small>Saturday–Thursday</small></label><label>Daily Math target<input aria-label="Daily Math target" type="number" min="1" max="10000" required value={draft.math} onChange={e => field('math', Number(e.target.value))} /><small>Saturday–Thursday</small></label><label>Friday English target<input aria-label="Friday English target" type="number" min="1" max="10000" required value={draft.fridayEnglish} onChange={e => field('fridayEnglish', Number(e.target.value))} /><small>Your extra practice day</small></label><label>Friday Math target<input aria-label="Friday Math target" type="number" min="1" max="10000" required value={draft.fridayMath} onChange={e => field('fridayMath', Number(e.target.value))} /><small>Your extra practice day</small></label><label>SAT exam date<input type="date" min={addDays(START, 1)} max="2036-10-09" required value={draft.exam} onChange={e => field('exam', e.target.value)} /></label><label>Target SAT score<input type="number" min="400" max="1600" step="10" required value={draft.target} onChange={e => field('target', Number(e.target.value))} /></label></div></section><section className="card settings-card"><div className="settings-intro"><IconBox icon={Sparkles} color="english" /><div><h3>Your space, your pace</h3><p>A comfortable environment makes it easier to show up.</p></div></div><div className="settings-row"><div><strong>Appearance</strong><span>Choose your favorite study atmosphere.</span></div><div className="segmented"><button type="button" className={draft.theme === 'dark' ? 'active' : ''} onClick={() => field('theme', 'dark')}><Moon size={15} /> Dark</button><button type="button" className={draft.theme === 'light' ? 'active' : ''} onClick={() => field('theme', 'light')}><Sun size={15} /> Light</button></div></div>{([{ key: 'sound', title: 'Sound effects', description: 'A soft chime for a little win.' }, { key: 'animations', title: 'Celebration animations', description: 'Progress rings, gentle motion, and tasteful confetti.' }, { key: 'reducedMotion', title: 'Reduce motion', description: 'Keep things still. Your system preference is respected too.' }, { key: 'quote', title: 'Daily inspiration', description: 'A little encouragement on your dashboard.' }, { key: 'reminder', title: 'Study reminder', description: 'Show a gentle reminder while this app is open. No background notifications.' }] as const).map(item => <div className="settings-row" key={item.key}><div><strong>{item.title}</strong><span>{item.description}</span></div><button className={`toggle ${draft[item.key] ? 'on' : ''}`} type="button" role="switch" aria-label={item.title} aria-checked={draft[item.key]} onClick={() => field(item.key, !draft[item.key])}><span /></button></div>)}{draft.reminder && <label className="reminder-field">Reminder time · your local time<input type="time" required value={draft.reminderTime} onChange={e => field('reminderTime', e.target.value)} /></label>}</section><div className="settings-save"><span><ShieldCheck size={15} /> Your progress stays on this device.</span><button className="primary-button" type="submit">Save changes <Check size={17} /></button></div></form><section className="card settings-card data-card"><div className="settings-intro"><IconBox icon={ArrowDownToLine} color="math" /><div><h3>Take your progress with you</h3><p>Export a backup or move your journey to another browser. Importing replaces the progress on this device.</p></div></div><div className="data-buttons"><button className="secondary-button" onClick={exportData}><ArrowDownToLine size={17} /> Export JSON</button><button className="secondary-button" onClick={() => input.current?.click()}><Upload size={17} /> Import JSON</button><input ref={input} className="visually-hidden" type="file" accept="application/json,.json" aria-label="Import progress file" onChange={e => { const file = e.target.files?.[0]; if (file) void importFile(file); e.target.value = '' }} /></div>{importError && <div className="notice error" role="alert">{importError}</div>}<p className="small-text muted">No account, no cloud sync. Clearing browser data removes local progress, so regular backups are a good idea.</p></section>{pending && <Modal title="Import progress backup" onClose={() => setPending(null)}><IconBox icon={Upload} color="math" /><h2>Bring your journey here?</h2><p>This backup contains {number(totalXP(pending))} XP and {Object.keys(pending.days).length} study days. It will replace this device’s current progress.</p><p className="muted">Export your current progress first if you want to keep a copy.</p><div className="data-buttons"><button className="secondary-button" onClick={exportData}>Export current progress</button><button className="primary-button" onClick={async () => { await onImport(pending); setDraft(pending.settings); setPending(null) }}>Replace and import</button></div></Modal>}</>
}
